const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');
const { RfqRegistry } = require('../services/rfqRegistry');

const server = http.createServer();
const io = new Server(server);

const pub = new Redis(process.env.REDIS_URL);
const sub = pub.duplicate();
io.adapter(createAdapter(pub, sub));

const rfqNsp = io.of(/^\/markets\/rfq-[a-zA-Z0-9]+$/);

rfqNsp.use(async (socket, next) => {
  const token = socket.handshake.auth.traderToken;
  if (!token) return next(new Error('Trader token required'));

  try {
    const trader = jwt.verify(token, process.env.MARKET_DATA_SECRET);
    const rfqId = socket.nsp.name.replace('/markets/rfq-', '');

    // Confirm that the trader's institution is a participant in this specific RFQ
    const isParticipant = await RfqRegistry.isParticipant(rfqId, trader.institutionId);
    if (!isParticipant) {
      return next(new Error('Access denied: firm not a counterparty to this RFQ'));
    }

    socket.trader = trader;
    next();
  } catch {
    next(new Error('Authorization validation failed'));
  }
});

rfqNsp.on('connection', (socket) => {
  const rfqId = socket.nsp.name.replace('/markets/rfq-', '');

  socket.on('get_private_quotes', async () => {
    const quotes = await fetchQuotesForRfq(rfqId);
    socket.emit('quote_update', quotes);
  });
});

server.listen(4008);
